from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

V = 16
E = 23

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return u * V + v + 1

solver = Glucose4()

# At least 23 edges
edge_vars = [edge_var(u, v) for u in range(V) for v in range(u+1, V)]
cnf = CardEnc.atleast(lits=edge_vars, bound=E, encoding=1)
for clause in cnf.clauses:
    solver.add_clause(clause)

# Girth >= 7 means no cycles of length 3, 4, 5, 6
# Length 3
for c in itertools.combinations(range(V), 3):
    solver.add_clause([-edge_var(c[0], c[1]), -edge_var(c[1], c[2]), -edge_var(c[0], c[2])])

# Length 4
for c in itertools.combinations(range(V), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[0])])

# Length 5
for c in itertools.combinations(range(V), 5):
    for p in itertools.permutations(c):
        # To avoid duplicates, fix the first element to be the minimum, and the second < last
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[0])])

# Length 6
for c in itertools.combinations(range(V), 6):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[5]:
            solver.add_clause([-edge_var(p[0], p[1]), -edge_var(p[1], p[2]), -edge_var(p[2], p[3]), -edge_var(p[3], p[4]), -edge_var(p[4], p[5]), -edge_var(p[5], p[0])])

print("Solving...")
result = solver.solve()
print("Satisfiable:", result)
if result:
    model = solver.get_model()
    edges = []
    for u in range(V):
        for v in range(u+1, V):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))
    print("Edges:", len(edges))

