from pysat.solvers import Glucose4
from pysat.card import CardEnc

V = 16
E_target = 23

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return u * V + v + 1

solver = Glucose4()

# At least 23 edges
edge_vars = [edge_var(u, v) for u in range(V) for v in range(u+1, V)]
cnf = CardEnc.atleast(lits=edge_vars, bound=E_target, encoding=1)
for clause in cnf.clauses:
    solver.add_clause(clause)

def get_short_cycle(edges):
    G = nx.Graph()
    G.add_nodes_from(range(V))
    G.add_edges_from(edges)

    try:
        cycle = nx.find_cycle(G)
        if len(cycle) <= 6:
            return [tuple(sorted(e[:2])) for e in cycle]
    except nx.NetworkXNoCycle:
        pass

    # find_cycle might not find the shortest cycle.
    # Let's use BFS to find the shortest cycle.
    for u in range(V):
        # BFS from u
        dist = {u: 0}
        parent = {u: None}
        q = [u]
        for curr in q:
            for nxt in G.neighbors(curr):
                if nxt not in dist:
                    dist[nxt] = dist[curr] + 1
                    parent[nxt] = curr
                    q.append(nxt)
                elif parent[curr] != nxt:
                    # Cycle found
                    cycle_len = dist[curr] + dist[nxt] + 1
                    if cycle_len <= 6:
                        # Reconstruct cycle edges
                        path1 = []
                        c = curr
                        while c is != None:
                            path1.append(c)
                            c = parent[c]
                        path2 = []
                        c = nxt
                        while c is != None:
                            path2.append(c)
                            c = parent[c]

                        # Find lowest common ancestor
                        lca = None
                        for p in path1:
                            if p in path2:
                                lca = p
                                break

                        cycle_edges = [(curr, nxt)]
                        c = curr
                        while c != lca:
                            cycle_edges.append((c, parent[c]))
                            c = parent[c]
                        c = nxt
                        while c != lca:
                            cycle_edges.append((c, parent[c]))
                            c = parent[c]

                        return [tuple(sorted(e)) for e in cycle_edges]
    return None

iterations = 0
while True:
