        break

    model = solver.get_model()
    edges = []
    for u in range(V):
        for v in range(u+1, V):
            if model[edge_var(u, v) - 1] > 0:
                edges.append((u, v))

    cycle = get_short_cycle(edges)
    if cycle is None:
        print("Found graph with edges:", len(edges))
        print(edges)
        break
    else:
        # Add clause to forbid this cycle
        clause = [-edge_var(u, v) for u, v in cycle]
        solver.add_clause(clause)
        iterations += 1
